mapper.select:
select r.*, i.title as itemTitle, i.seller_id as sellerId, u.nickname as buyerNickname
from reservation r
left join item i on r.item_id = i.id
left join `user` u on r.buyer_id = u.id


        and r.buyer_id = #{userId}
        and i.seller_id = #{userId}

    and r.status = #{status}

order by r.created_at desc

select count(*)
from reservation r
left join item i on r.item_id = i.id

    where r.buyer_id = #{userId}
    where i.seller_id = #{userId}

and r.status = 'PENDING'

select count(*) from reservation
where item_id = #{itemId} and buyer_id = #{buyerId}
  and status in ('PENDING', 'CONFIRMED')
